/* LOOK42: cosmetic frames only; no inventory, combat or movement changes. Embedded for offline index.html. */
(()=>{'use strict';const API=globalThis.MALE_LOOK42={ready:false,error:null,animations:{},frames:[],revision:42};const sheet=new Image();
const notify=()=>globalThis.SH?.appearance42?.refresh();
sheet.onerror=()=>{API.error='Không tải được ngoại hình';notify()};
sheet.onload=async()=>{try{const sw=sheet.naturalWidth/4,sh=sheet.naturalHeight/8,w=Math.ceil(sw),h=Math.ceil(sh),rows=[],loads=[];let reference=0;
 for(let row=0;row<8;row++){const frames=[];for(let col=0;col<4;col++){const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');g.drawImage(sheet,col*sw,row*sh,sw,sh,0,0,w,h);const d=g.getImageData(0,0,w,h).data;let y0=h,y1=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(d[(y*w+x)*4+3]>64){y0=Math.min(y0,y);y1=Math.max(y1,y)}if(row===0&&col===0)reference=Math.max(1,y1-y0+1);
 const f={u:c.toDataURL('image/png'),w,h,ax:w/2,fy:y1+1,sc:177/reference,row42:row,col42:col};
 const grips=[[[.635,.664],[.635,.662],[.639,.669],[.645,.677]],[[.639,.666],[.641,.657],[.642,.666],[.647,.672]],[[.645,.643],[.644,.611],[.649,.636],[.648,.638]],[[.627,.611],[.607,.622],[.650,.621],[.637,.606]],[[.609,.613],[.581,.580],[.536,.610],[.572,.587]],[[.676,.527],[.578,.606],[.593,.582],[.578,.569]],[[.68,.24],[.72,.50],[.70,.72],[.72,.53]]];if(grips[row])f.grip42={x:grips[row][col][0],y:grips[row][col][1],s:1};
 const im=new Image();f.i=im;loads.push(new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=reject}));im.src=f.u;frames.push(f);API.frames.push(f)}rows.push(frames)}
 const a=API.animations;a.idle=rows[0];a.idleU=rows[1];a.walkD=rows[2];a.walkU=rows[3];a.walk=rows[4];a.run=rows[5];a.runD=rows[2];a.runU=rows[3];
 for(const n of ['punch','kick','punchD','punchU','kickD','kickU','chop','atk'])a[n]=rows[6];a.pick=[rows[7][0]];a.hurt=[rows[7][1]];a.die=[rows[7][2]];a.dodge=[rows[7][3]];
 await Promise.all(loads);API.ready=true;notify();}catch(e){API.error=String(e?.message||e);notify();console.error('[LOOK42]',API.error)}};
sheet.src='data:image/png;base64,';})();
